function validate(input) {
  const [{ Sales = [] }] = input;
  const keys = new Set();
  for (const row of Sales) {
    if (row.some((v) => v === null)) return 'Sales rows may not contain null.';
    const key = `${row[0]}|${row[2]}`;
    if (keys.has(key)) return `(sale_id ${row[0]}, year ${row[2]}) appears twice in Sales.`;
    keys.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const Sales = [];
  const used = new Set();
  if (size === 'small') {
    // Few products, years and prices so first-year ties and identical rows show up.
    const rows = Math.floor(rand() * 9);
    for (let i = 0; i < rows; i++) {
      const saleId = 1 + Math.floor(rand() * 5);
      const year = pick([2008, 2009, 2010, 2011]);
      if (used.has(`${saleId}|${year}`)) continue;
      used.add(`${saleId}|${year}`);
      Sales.push([saleId, pick([100, 200, 300]), year, pick([1, 10, 12, 15]), pick([5000, 9000, 100])]);
    }
  } else {
    for (let saleId = 1; saleId <= 2000; saleId++) {
      Sales.push([saleId, 1 + Math.floor(rand() * 300), 2000 + Math.floor(rand() * 20), 1 + Math.floor(rand() * 50), 10 * (1 + Math.floor(rand() * 900))]);
    }
  }
  return [{ Sales }];
}
